/**
 * Customer model.
 *
 * `code` is generated by customerService (CUS-0001) and is unique among live
 * rows. Soft-deleted customers release their code because the unique index is
 * partial on { deletedAt: null }.
 */
'use strict';

const mongoose = require('mongoose');
const {
  CUSTOMER_TYPES,
  CUSTOMER_SOURCES,
  DISCO_COMPANIES,
} = require('../config/crm');
const softDeletePlugin = require('./plugins/softDelete');

const CNIC_PATTERN = /^\d{5}-?\d{7}-?\d$/;

const gpsSchema = new mongoose.Schema(
  {
    lat: {
      type: Number,
      default: null,
      min: [-90, 'Latitude must be between -90 and 90'],
      max: [90, 'Latitude must be between -90 and 90'],
    },
    lng: {
      type: Number,
      default: null,
      min: [-180, 'Longitude must be between -180 and 180'],
      max: [180, 'Longitude must be between -180 and 180'],
    },
  },
  { _id: false }
);

const customerSchema = new mongoose.Schema(
  {
    code: {
      type: String,
      required: [true, 'Customer code is required'],
      trim: true,
      uppercase: true,
      maxlength: [20, 'Customer code cannot exceed 20 characters'],
    },
    name: {
      type: String,
      required: [true, 'Customer name is required'],
      trim: true,
      maxlength: [120, 'Name cannot exceed 120 characters'],
    },
    phone: {
      type: String,
      required: [true, 'Phone number is required'],
      trim: true,
      maxlength: [20, 'Phone cannot exceed 20 characters'],
      validate: {
        validator: (value) => /^[0-9+\-()\s]{7,20}$/.test(value),
        message: 'Enter a valid phone number',
      },
    },
    whatsapp: {
      type: String,
      trim: true,
      default: '',
      maxlength: [20, 'WhatsApp number cannot exceed 20 characters'],
      validate: {
        validator: (value) => !value || /^[0-9+\-()\s]{7,20}$/.test(value),
        message: 'Enter a valid WhatsApp number',
      },
    },
    cnic: {
      type: String,
      trim: true,
      default: '',
      maxlength: [15, 'CNIC cannot exceed 15 characters'],
      validate: {
        validator: (value) => !value || CNIC_PATTERN.test(value),
        message: 'Enter a valid CNIC (12345-1234567-1)',
      },
    },
    address: {
      type: String,
      trim: true,
      default: '',
      maxlength: [250, 'Address cannot exceed 250 characters'],
    },
    city: {
      type: String,
      trim: true,
      default: '',
      maxlength: [80, 'City cannot exceed 80 characters'],
    },
    area: {
      type: String,
      trim: true,
      default: '',
      maxlength: [80, 'Area cannot exceed 80 characters'],
    },
    gps: {
      type: gpsSchema,
      default: () => ({}),
    },
    electricityReferenceNo: {
      type: String,
      trim: true,
      default: '',
      maxlength: [60, 'Electricity reference number cannot exceed 60 characters'],
    },
    disco: {
      type: String,
      enum: {
        values: ['', ...DISCO_COMPANIES],
        message: 'Select a valid DISCO',
      },
      default: '',
    },
    type: {
      type: String,
      enum: { values: CUSTOMER_TYPES, message: 'Select a valid customer type' },
      default: 'residential',
      index: true,
    },
    source: {
      type: String,
      enum: { values: CUSTOMER_SOURCES, message: 'Select a valid source' },
      default: 'other',
      index: true,
    },
    notes: {
      type: String,
      trim: true,
      default: '',
      maxlength: [1000, 'Notes cannot exceed 1000 characters'],
    },
    assignedTo: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'User',
      default: null,
      index: true,
    },
    createdBy: { type: mongoose.Schema.Types.ObjectId, ref: 'User', default: null },
  },
  {
    timestamps: true,
    toJSON: {
      virtuals: true,
      transform(_doc, ret) {
        delete ret.__v;
        return ret;
      },
    },
    toObject: { virtuals: true },
  }
);

customerSchema.index(
  { code: 1 },
  { unique: true, partialFilterExpression: { deletedAt: null } }
);
customerSchema.index({ name: 1 });
customerSchema.index({ phone: 1 });
customerSchema.index({ city: 1 });
customerSchema.index({ createdAt: -1 });

customerSchema.virtual('typeLabel').get(function typeLabel() {
  const { CUSTOMER_TYPE_LABELS } = require('../config/crm');
  return CUSTOMER_TYPE_LABELS[this.type] || this.type;
});

customerSchema.virtual('gpsText').get(function gpsText() {
  if (!this.gps || this.gps.lat === null || this.gps.lng === null) return '';
  if (this.gps.lat === undefined || this.gps.lng === undefined) return '';
  return `${this.gps.lat}, ${this.gps.lng}`;
});

customerSchema.plugin(softDeletePlugin);

module.exports = mongoose.model('Customer', customerSchema);
